 * 一变，编辑态会留在另一个角色的卡上。
 */
watch(() => props.character.rowIndex, () => { editing.value = false; });
/* 写入通道没了（切到只读模式）也要退出，否则留着一排改不动的输入框 */
watch(() => props.editable, (v) => { if (!v) editing.value = false; });

