 * 在架空纪年里点一下就落进一个永远空白的月份。
 */
.bara-cal__grid :deep(.n-calendar-header__extra) { display: none; }
/* 标题插槽要占满整行，自己的导航才能靠右 */
.bara-cal__grid :deep(.n-calendar-header__title) { flex: 1 1 auto; }

.bara-cal__head {
  display: flex;
