                  :value="f.text"
                  multiline
                  :pending="pending === fieldKey(f.sheetName, f.rowIndex, f.label)"
                  @submit="(v) => emit('setCell', f.sheetName, f.rowIndex, f.label, v)"
                />
                <template v-else>{{ f.text }}</template>
              </dd>
            </div>
          </dl>
        </NCollapseItem>
      </NCollapse>

      <template v-if="relations">
        <NDivider class="bara-bio__rule" />
        <section>
          <h3 class="bara-bio__h">{{ t('sheet.section.relations', lang) }}</h3>
          <SectionList
            :section="relations"
            :body-columns="['关系描述']"
            :editing="editing"
            :pending="pending"
            @set-cell="(...a) => emit('setCell', ...a)"
          />
        </section>
      </template>

      <template v-if="chronicle">
        <NDivider class="bara-bio__rule" />
        <section>
          <h3 class="bara-bio__h">{{ t('sheet.section.chronicle', lang) }}</h3>
          <SectionList
            :section="chronicle"
            title-column="记录内容"
            :tag-columns="['发生时间', '与今天的关系', '核心记忆']"
            :editing="editing"
            :pending="pending"
            @set-cell="(...a) => emit('setCell', ...a)"
          />
        </section>
      </template>

