            {{ o.label }}
          </NRadioButton>
        </NRadioGroup>
      </SettingsRow>

      <SettingsRow :label="t('settings.dockIcons', ui.lang)">
        <NRadioGroup :value="bool(ui.dockIcons)" size="small" @update:value="() => ui.toggleDockIcons()">
          <NRadioButton v-for="o in onOff" :key="o.value" :value="o.value">
            {{ o.label }}
          </NRadioButton>
        </NRadioGroup>
      </SettingsRow>

      <SettingsRow
