        <NInputNumber
          :value="ui.contentHeight"
          :min="30"
          :max="90"
          :step="10"
          :format="vh.format"
          :parse="vh.parse"
          size="small"
          class="bara-set__num"
          @update:value="(v: number | null) => ui.setContentHeight(v ?? 60)"
