      <SettingsRow
        :label="t('settings.fullWidth', ui.lang)"
        :hint="t('settings.fullWidth.hint', ui.lang)"
      >
        <NRadioGroup
          :value="bool(ui.fullWidth)"
          size="small"
          @update:value="(v: string) => ui.setFullWidth(v === 'on')"
