          <NRadioButton v-for="o in onOff" :key="o.value" :value="o.value">
            {{ o.label }}
          </NRadioButton>
        </NRadioGroup>
      </SettingsRow>
    </SettingsGroup>

    \x3c!-- 游戏模式与规则 --\x3e
