  height: auto;
  padding: var(--bara-space-3) var(--bara-space-4);
  border-radius: 0;
  background: var(--bara-color-surface-sunken);
  font-size: var(--bara-font-size-sm);
  font-weight: var(--bara-font-weight-medium);
}
